Ecco un'implementazione completa basata su `heapq`:

```python
import heapq
from dataclasses import dataclass, field
from typing import Any

@dataclass(order=True)
class PriorityItem:
    priority: int
    item: Any = field(compare=False)

class PriorityQueue:
    """Coda con priorità min-heap (priorità più bassa = servita prima)."""

    def __init__(self) -> None:
        self._heap: list[PriorityItem] = []

    def push(self, item: Any, priority: int) -> None:
        """Inserisce un elemento con la priorità specificata."""
        heapq.heappush(self._heap, PriorityItem(priority, item))

    def pop(self) -> Any:
        """Rimuove e restituisce l'elemento con priorità minima."""
        if not self._heap:
            raise IndexError("pop da coda vuota")
        return heapq.heappop(self._heap).item

    def peek(self) -> Any:
        """Restituisce l'elemento con priorità minima senza rimuoverlo."""
        if not self._heap:
            raise IndexError("peek su coda vuota")
        return self._heap[0].item

    def __len__(self) -> int:
        return len(self._heap)
```

Esempio d'uso:
```python
pq = PriorityQueue()
pq.push('task urgente', priority=1)
pq.push('task normale', priority=5)
print(pq.pop())  # 'task urgente'
```
